const d = $input.first().json;
const messages = typeof d.messages === 'string' ? JSON.parse(d.messages) : (d.messages || []);
const conversation = messages.map(m => (m.role === 'user' ? 'USUARIO' : 'ASISTENTE') + ': ' + m.content).join('\n\n');

const baseline = {
  identity: d.baseline_identity, tone: d.baseline_tone, priorities: d.baseline_priorities,
  red_lines: d.baseline_red_lines, visit_checklist: d.baseline_visit_checklist,
  materials_pref: d.baseline_materials_pref, trades_pref: d.baseline_trades_pref,
  jurisdiction: d.baseline_jurisdiction
};

const systemPrompt = `Eres un extractor de datos estructurados. Recibes la transcripcion de una conversación de onboarding entre un asistente IA y un profesional de la arquitectura técnica. Tu tarea es estructurar lo que dijo el profesional en un JSON con 8 secciones siguiendo el schema exacto.

**Reglas estrictas**:
- Devuelve SOLO un objeto JSON valido, sin markdown, sin texto antes o despues.
- Si una sección no fue cubierta o el usuario explicitamente dijo "acepto el baseline / lo genérico", usa los valores del BASELINE proporcionado.
- Si el usuario dijo algo que difiere del baseline, prioriza lo que dijo el usuario.
- Sigue EXACTAMENTE el schema. No inventes campos nuevos.

**Schema exacto**:
{
  "identity": {"nombre_estudio":"","persona_principal":"","ciudad":"","ambito":[],"tamano":"","anos_exp":0,"colegiado_no":""},
  "tone": {"clientes":{"formalidad":"","tutea":true,"tecnicidad":"","longitud":"","explica_terminos":true},"gremios":{"formalidad":"","longitud":"","tecnicidad":""},"promotores":{"formalidad":"","longitud":"","tecnicidad":""}},
  "priorities": [{"orden":0,"prioridad":"","detalle":""}],
  "red_lines": [{"id":"","texto":""}],
  "visit_checklist": [{"pregunta":"","contexto":""}],
  "materials_pref": {"gama_default":"","prefiere_local":true,"marcas_preferidas_por_categoria":{}},
  "trades_pref": {"criterios_seleccion":[],"trade_to_contact":{},"blacklist":[]},
  "jurisdiction": {"ccaa":"","ayuntamientos_habituales":[],"normativa_autonomica":[],"normativa_estatal_siempre":[]}
}

**BASELINE de referencia (úsalo si una sección no fue cubierta o el usuario lo aceptó)**:
${JSON.stringify(baseline, null, 2).substring(0, 4000)}`;

const userPrompt = 'TRANSCRIPCION DE LA CONVERSACION:\n\n' + conversation + '\n\nExtrae el JSON estructurado siguiendo el schema. Recuerda: SOLO el JSON, sin markdown.';

return [{ json: {
  agent_name: 'agent_onboarding_extract',
  project_id: null,
  prompt_system: systemPrompt,
  prompt_user: userPrompt,
  model: 'gpt-4o',
  temperature: 0.2,
  _session_id: d.session_id,
  _contact_email: d.contact_email,
  _contact_name: d.contact_name
}}];

const llm = $input.first().json;
const pre = $('Build Extract Prompt').first().json;
const raw = (llm.text || '').trim();
let extracted;
try {
  const m = raw.match(/\{[\s\S]*\}/);
  extracted = m ? JSON.parse(m[0]) : null;
} catch(e) { extracted = null; }

if (!extracted) {
  return [{ json: { extract_failed: true, error: 'no JSON in LLM response', raw_preview: raw.substring(0,500), _session_id: pre._session_id, _contact_email: pre._contact_email, _contact_name: pre._contact_name } }];
}

const sec = (k, fb) => extracted[k] || fb || (Array.isArray(fb) ? [] : {});

return [{ json: {
  extract_failed: false,
  identity_json: JSON.stringify(sec('identity', {})),
  tone_json: JSON.stringify(sec('tone', {})),
  priorities_json: JSON.stringify(sec('priorities', [])),
  red_lines_json: JSON.stringify(sec('red_lines', [])),
  visit_checklist_json: JSON.stringify(sec('visit_checklist', [])),
  materials_pref_json: JSON.stringify(sec('materials_pref', {})),
  trades_pref_json: JSON.stringify(sec('trades_pref', {})),
  jurisdiction_json: JSON.stringify(sec('jurisdiction', {})),
  _session_id: pre._session_id,
  _contact_email: pre._contact_email,
  _contact_name: pre._contact_name,
  _profile_summary: 'Estudio: ' + (sec('identity', {}).nombre_estudio || '?') + ' | Tono: ' + ((sec('tone', {}).clientes || {}).formalidad || '?') + ' | Prioridades: ' + (Array.isArray(sec('priorities', [])) ? sec('priorities', []).length : 0)
}}];

const profile = $('Insert Studio Profile').first().json;
const summary = $('Parse Extracted JSON').first().json._profile_summary;
const html = `<div style="font-family:system-ui,sans-serif;color:#222;max-width:680px">
<h2>Onboarding completado</h2>
<p>Un nuevo profesional ha completado el onboarding conversacional de ArquitAI.</p>
<table style="border-collapse:collapse;font-size:14px;margin-top:12px">
  <tr><td style="padding:6px 12px;color:#666">studio_id</td><td style="padding:6px 12px;font-family:monospace">${profile.studio_id}</td></tr>
  <tr><td style="padding:6px 12px;color:#666">Resumen</td><td style="padding:6px 12px">${summary}</td></tr>
</table>
<p style="margin-top:18px">Este perfil ya esta active=true. El baseline anterior queda inactivo. Los 11 agentes nucleo leeran este perfil dinamicamente cuando se haga el refactor (bloque 22).</p>
<p style="font-size:12px;color:#888;margin-top:24px">agent_onboarding_extract - generado ${new Date().toISOString()}</p>
</div>`;
return [{ json: { html, subject: '[ArquitAI] Onboarding completado - profile creado' } }];
